public class NotFoundException : Exception
{
    public string ResourceType { get; }

    public NotFoundException(string resourceType, string id)
        : base($"{resourceType} with ID {id} was not found.")
    {
        ResourceType = resourceType;
    }
}

public class ValidationException : Exception
{
    public IReadOnlyList<string> Errors { get; }

    public ValidationException(IEnumerable<string> errors)
        : base("Validation failed.")
    {
        Errors = errors.ToList();
    }
}

public class DomainExceptionFilter : IExceptionFilter
{
    public async ValueTask OnExceptionAsync(IExceptionContext context)
    {
        switch (context.Exception)
        {
            case NotFoundException ex:
                context.Error = Error.Create(
                    ex.Message,
                    code: "NOT_FOUND",
                    extensions: new { resourceType = ex.ResourceType });
                break;

            case ValidationException ex:
                context.Error = Error.Create(
                    ex.Message,
                    code: "VALIDATION_ERROR",
                    extensions: new { errors = ex.Errors });
                break;
        }

        context.Exception = null;
    }
}
